export MSYS_NO_PATHCONV=1; cat > .qa/inter.mjs <<'EOF'
import { chromium } from "@playwright/test";
const bases = { main: "http://localhost:3102", branch: "http://localhost:3101" };
const b = await chromium.launch(); const res = { main: { h1: [], waiting: [], cls: [] }, branch: { h1: [], waiting: [], cls: [] } };
for (let i = 0; i < 12; i++) for (const [name, base] of Object.entries(bases)) {
  const c = await b.newContext({ baseURL: base, storageState: "e2e/.auth.json", viewport: { width: 1440, height: 900 } });
  const p = await c.newPage();
  await p.addInitScript(() => { window.__m = { cls: 0 }; new PerformanceObserver(l => { for (const e of l.getEntries()) window.__m.cls += e.value; }).observe({ type: "layout-shift", buffered: true });
    const tick = () => { if (!window.__m.h1 && document.querySelector("h1")) window.__m.h1 = performance.now(); if (!window.__m.waiting && document.querySelector("details[aria-label='Waiting for you']")) window.__m.waiting = performance.now(); requestAnimationFrame(tick); }; requestAnimationFrame(tick); });
  await p.goto("/"); await p.waitForTimeout(2500);
  const m = await p.evaluate(() => window.__m); if (i > 0) { res[name].h1.push(m.h1); res[name].waiting.push(m.waiting); res[name].cls.push(m.cls); }
  await c.close();
}
const med = a => a.sort((x, y) => x - y)[Math.floor(a.length / 2)];
for (const n of Object.keys(res)) console.log(n, "h1", med(res[n].h1).toFixed(0), "waiting", med(res[n].waiting).toFixed(0), "cls", med(res[n].cls).toFixed(3), "all h1", res[n].h1.map(x => x.toFixed(0)).join(","));
await b.close();
EOF
